// Private, self-contained study map and printable A4 edition.
export const ORMI_MAP_HTML = "<!doctype html>\n<html lang=\"el\">\n<head>\n<meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"color-scheme\" content=\"light\">\n<title>Ο χάρτης της ορμής · Μιχάλης</title>\n<style>\n:root{--ink:#132731;--muted:#435966;--surface:#fff;--bg:#eef3f2;--rule:#d5e1e2;--accent:#0e6555}\n*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.55 system-ui,sans-serif}main{max-width:1050px;margin:auto;padding:24px 20px 50px}header{padding:25px 0 19px}small.kicker{display:block;font-weight:750;color:#0e6555;letter-spacing:.12em;text-transform:uppercase}h1,h2{font-family:Georgia,'Times New Roman',serif;line-height:1.08;letter-spacing:-.015em;margin:.23em 0}.lede{color:var(--muted);max-width:54ch;margin:.65em 0}h1{font-size:clamp(2.45rem,7vw,4.6rem)}h2{font-size:clamp(1.7rem,4vw,2.5rem)}h3{margin:.4em 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(166px,1fr));gap:8px;margin:0 0 19px}button,select,input{font:inherit}button,select{color:var(--ink);background:white;border:1px solid var(--rule);border-radius:9px;padding:8px 12px;min-height:44px;cursor:pointer}button:focus-visible,select:focus-visible,input:focus-visible,summary:focus-visible, a:focus-visible{outline:3px solid #235cb2;outline-offset:3px}nav button{text-align:left;line-height:1.18}nav button strong{color:var(--tone);margin-right:.45em}nav button[aria-pressed=true]{background:var(--tone);color:white;border-color:var(--tone)}nav button[aria-pressed=true] strong{color:inherit}\n.workspace{background:white;border:1px solid var(--rule);border-top:5px solid var(--accent);border-radius:15px;padding:clamp(15px,3.3vw,32px)}.family-tag,.hook{color:var(--accent);font-weight:740}.route{max-width:73ch}.motion{background:#f4f7f8;border-radius:12px;padding:12px;margin:20px 0}.motion h3{font-size:1.06rem}.motion svg{display:block;width:100%;height:auto;max-height:245px;margin:0 auto}.motion line{vector-effect:non-scaling-stroke}.controls{display:flex;flex-wrap:wrap;gap:8px;align-items:center}.controls label{flex:1;min-width:135px;display:flex;align-items:center;gap:8px}.controls input{width:100%;min-height:36px;accent-color:var(--accent)}.controls button[aria-pressed=true],#play{background:var(--accent);color:white;border-color:var(--accent)}.motionNote{margin:.55em 0 .3em;color:var(--muted);min-height:1.55em}.cases{display:grid;gap:7px}details{border:1px solid var(--rule);border-radius:9px;padding:0 13px}summary{cursor:pointer;padding:10px 0;font-weight:710}summary span{color:var(--accent);margin-right:.55em}details p{margin:0 0 11px}details .example{padding:10px;background:#f4f7f8;border-radius:6px}details .ref{font-size:.9rem;color:var(--muted)}a{color:#1954a4}.index{margin-top:18px;background:white}.index p{overflow-wrap:anywhere}.sources{margin-top:17px;font-size:.9rem}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;clip:rect(0,0,0,0);overflow:hidden;white-space:nowrap}.legend{font-size:.88rem;color:var(--muted)}\n@media(max-width:420px){main{padding:17px 12px 35px}.grid{grid-template-columns:1fr 1fr}.controls select{max-width:100%}.controls label{flex-basis:100%}}\n</style>\n</head><body><main>\n<header><small class=\"kicker\">Μιχάλης / Φυσική Β΄ Λυκείου</small><h1>Ορμή &amp; κρούσεις</h1>\n<p class=\"lede\">Διάλεξε μια οικογένεια. Παρατήρησε τι αλλάζει από φάση σε φάση και άνοιξε τις παραλλαγές για να δεις παραδείγματα και ασκήσεις.</p></header>\n<nav id=\"families\" class=\"grid\" aria-label=\"Οικογένειες ασκήσεων\"></nav>\n<section class=\"workspace\" aria-labelledby=\"title\">\n<span class=\"family-tag\" id=\"tag\"></span><h2 id=\"title\"></h2><p class=\"hook\" id=\"hook\"></p><p class=\"route\" id=\"route\"></p>\n<section class=\"motion\" aria-labelledby=\"scene-title\"><h3 id=\"scene-title\"></h3>\n<div class=\"controls\" id=\"scenarios\"></div>\n<svg id=\"scene\" viewBox=\"0 0 420 178\" role=\"img\" aria-labelledby=\"scene-title\" xmlns=\"http://www.w3.org/2000/svg\"></svg>\n<p class=\"motionNote\" id=\"note\"></p>\n<div class=\"controls\"><button id=\"play\" type=\"button\">▶ Κίνηση</button><label><span class=\"legend\">Εξέλιξη</span><input id=\"seek\" type=\"range\" min=\"0\" max=\"1000\" value=\"0\"></label></div>\n</section>\n<div id=\"cases\" class=\"cases\"></div>\n<details class=\"index\"><summary>Ευρετήριο ασκήσεων αυτής της οικογένειας</summary><div id=\"index\"></div></details>\n</section>\n<div class=\"sources\" id=\"sources\"></div>\n</main>\n<script>\nconst MAP = {\"families\": [[\"A\", \"Ορμή, δύναμη και διαγράμματα\", \"Ξεκίνα από τα βέλη, όχι από τις πράξεις.\", \"Ένα σώμα → διάλεξε θετική φορά → βρες p ή Δp. Για σύστημα, πρόσθεσε τις ορμές διανυσματικά. Ο ρυθμός μεταβολής είναι η συνισταμένη, όχι κατ’ ανάγκη μία από τις δυνάμεις.\", \"force\", [[\"Ίδια ταχύτητα, ίδια ορμή ή ίδια K;\", \"Με ίδια υ, η μεγαλύτερη μάζα έχει μεγαλύτερη p. Με ίσα μέτρα p, το ελαφρύτερο έχει μεγαλύτερη K. Με ίδια K, ισχύει p = √(2mK).\", \"Ίδια K και m₂ = 4m₁ → p₂ = 2p₁.\", \"Τρ. 4.67–4.69, ΤΘ 16105/2.1, 16227/2.1\"], [\"Ίδια, αντίθετη ή λοξή φορά\", \"Δp = pτελ − pαρχ ως διανύσματα. Στην αναστροφή προσθέτεις τα μέτρα. Για κάθετες ορμές χρησιμοποιείς Πυθαγόρειο.\", \"Από 12 προς τα δεξιά σε 9 προς τα πάνω → |Δp| = 15 kg·m/s.\", \"Τρ. 4.74–4.78, 4.105\"], [\"Ποια δύναμη αλλάζει την ορμή;\", \"ΣF = Δp/Δt για μέση συνισταμένη. Με σταθερή ΣF, Δp = ΣF·Δt. Με πλάγιο τράβηγμα, η κατακόρυφη συνιστώσα αλλάζει την αντίδραση Ν και άρα την τριβή.\", \"Βάρος 20 N, τράβηγμα 8 N δεξιά και 6 N πάνω, μ = 0,5 → Ν = 14 N, τριβή 7 N, ΣF = 1 N δεξιά.\", \"Τρ. 4.70–4.73, 4.101–4.102, ΤΘ 21401/2.2\"], [\"Τρία διαγράμματα, τρεις κινήσεις\", \"Κλίση x–t → υ. Κλίση p–t → ΣF. Προσημασμένο εμβαδό ΣF–t → Δp. Οριζόντιο p–t σημαίνει σταθερή ορμή, όχι απαραίτητα ακινησία.\", \"ΣF ανεβαίνει από 4 σε 10 N σε 4 s → εμβαδό 28 N·s. Από ηρεμία, για 7 kg, υ = 4 m/s.\", \"Τρ. 4.79, 4.83, 4.106, ΤΘ 16037/2.2, 16049/2.2, 16875/2.2\"], [\"Σύστημα και δράση–αντίδραση\", \"Οι αμοιβαίες ωθήσεις είναι αντίθετες. Αν οι εξωτερικές ωθήσεις στα δύο σώματα είναι αμελητέες, τότε και οι Δp₁, Δp₂ είναι αντίθετες. Μηδενική συνολική ορμή δεν σημαίνει ότι όλα τα σώματα είναι ακίνητα.\", \"2 kg με +6 m/s και 3 kg με −4 m/s → P = 0, ενώ και τα δύο κινούνται.\", \"Τρ. 4.84–4.85, ΤΘ 21388/2.1, 15997/2.1, 20047/2.1\"]]], [\"B\", \"Τοίχος, πάτωμα και αναπηδήσεις\", \"Η στήριξη δίνει ώθηση. Για το ένα σώμα δεν γράφω ΑΔΟ.\", \"Πτήση ή ομαλή κίνηση πριν → Δp για τη σύντομη επαφή → νέα κίνηση μετά. Χώρισε τους χρόνους και μη μπερδεύεις τη δύναμη επαφής με τη συνισταμένη.\", \"bounce\", [[\"Κάθετα σε ακλόνητο τοίχο\", \"Η ταχύτητα αντιστρέφεται. Αν ο τοίχος είναι η μόνη οριζόντια δύναμη, η μέση δύναμή του είναι Δpₓ/Δt. Αν διπλασιάσεις τον χρόνο για ίδια Δp, η μέση δύναμη υποδιπλασιάζεται.\", \"1,5 kg φτάνει με 8 και γυρίζει με 2 m/s σε 0,2 s → 75 N μακριά από τον τοίχο.\", \"Τρ. 4.80–4.81, 4.103, Σχ. 10\"], [\"Λοξά σε λείο, ακλόνητο τοίχο\", \"Η παράλληλη συνιστώσα μένει ίδια. Η κάθετη αντιστρέφεται και, αν η κρούση είναι ελαστική, κρατά και το μέτρο της. Αν υπάρχει τριβή, δεν εξασφαλίζεται σταθερή παράλληλη συνιστώσα.\", \"(υκάθ., υπαρ.) = (+3,+4) → (−3,+4) σε ελαστική κρούση. Ίδια K, αλλά Δpκάθ. = −6m.\", \"Πόστερ 5\"], [\"Πτώση και αναπήδηση στο πάτωμα\", \"Στον αέρα: ΑΔΜΕ. Στην κρούση: με θετικά πάνω, Δp = m(υκάτω + υπάνω) και Νμ − mg = Δp/Δt. Στην κορυφή p = 0, όχι ΣF = 0.\", \"0,5 kg φτάνει με 30, φεύγει με 10 m/s και μένει σε επαφή 0,25 s → Δp = 20 N·s, Νμ = 85 N για g = 10.\", \"Τρ. 4.82, 4.104, ΤΘ 16120/2.2, Σχ. 5\"], [\"Πολλές αναπηδήσεις, με ή χωρίς αρχική υ\", \"Για κατακόρυφη αρχική υ, φτάνει με √(υ₀²+2gh₀), είτε το ρίξεις πάνω είτε κάτω. Αλλάζει ο χρόνος. Τα επόμενα ύψη απαιτούν δεδομένα για κάθε κρούση.\", \"Αφήνεται από 10 m. Αν σε κάθε επαφή μένει το 70% της Κ, οι κορυφές είναι 7 → 4,9 → 3,43 m. Μετά την τρίτη κορυφή ξαναπέφτει.\", \"Επέκταση Τρ. 4.104 και Πόστερ 4, 40\"], [\"Σφηνώνεται σε ακλόνητο τοίχο\", \"Στη διάρκεια της διείσδυσης, το έργο της αντίστασης μηδενίζει την Κ. Αν η αντίσταση είναι σταθερή, |W| = Fd. Για χρόνο χρησιμοποιώ και ώθηση. Δεν διατηρείται η ορμή του μικρού σώματος.\", \"Μικρό σώμα με Κ = 12 J σταματά σε 0,03 m → σταθερή αντίσταση 400 N.\", \"ΤΘ 16045/2.2, Πόστερ 34\"]]], [\"C\", \"Πλαστική κρούση: κολλάνε\", \"Όποια κι αν είναι η αρχική κίνηση, μετά υπάρχει μία κοινή ταχύτητα.\", \"ΑΔΟ στον άξονα χωρίς σημαντική εξωτερική ώθηση → V = Pπριν/(m₁+m₂). Για την απώλεια, συγκρίνω τις συνολικές κινητικές αμέσως πριν και αμέσως μετά.\", \"stick\", [[\"Ο στόχος ήταν ακίνητος\", \"Ο κινούμενος στόχος μετά έχει κοινή ταχύτητα με το σώμα που τον χτύπησε. Για αρχικά ακίνητο στόχο, Kμετά/Kπριν = m/(m+M). Δεν χρησιμοποιείται ο ίδιος λόγος όταν κινούνται και οι δύο.\", \"Ίσες μάζες, μία αρχικά ακίνητη → η κοινή υ είναι η μισή και μένει το 50% της αρχικής Κ.\", \"Τρ. 4.86–4.87, 4.91, ΤΘ 21853/2.1, 19652/2.2\"], [\"Ίδια φορά: το πίσω προλαβαίνει\", \"Πρόσθεσε τις δύο θετικές ορμές. Η V βρίσκεται ανάμεσα στις δύο αρχικές ταχύτητες. Το γρήγορο επιβραδύνεται, το αργό επιταχύνεται.\", \"1 kg στα 8 και 3 kg στα 4 m/s → V = 5 m/s. Η συνολική Κ πέφτει από 56 σε 50 J.\", \"Τρ. 4.88, 4.111\"], [\"Αντίθετες φορές: ποιος παρασύρει ποιον;\", \"Αφαιρούνται οι ορμές. Το συσσωμάτωμα κινείται προς τη μεγαλύτερη αρχική ορμή σε μέτρο. Ίσα μέτρα → V = 0, όχι Κπριν = 0.\", \"2 kg με +4 και 1 kg με −8 m/s → V = 0. Και τα 48 J της αρχικής Κ χάνονται από την κίνηση.\", \"Τρ. 4.89–4.90, 4.92, ΤΘ 16046/2.2, 16708/2.1\"], [\"Κάθετες διευθύνσεις ή πτώση σε καρότσι\", \"Σε ελεύθερο οριζόντιο επίπεδο γράφεις ΑΔΟ στους δύο οριζόντιους άξονες. Αν ένα σώμα πέφτει κατακόρυφα σε καρότσι, το δάπεδο δίνει κατακόρυφη ώθηση και κρατάς μόνο την οριζόντια ΑΔΟ.\", \"Δύο ίσες μάζες, η μία με 3 m/s ανατολικά, η άλλη με 4 προς βορρά → Vₓ = 1,5, Vᵧ = 2, |V| = 2,5 m/s.\", \"Πόστερ 20, 30\"], [\"Δίνεται ποσοστό ή ζητούν δύναμη\", \"Απώλεια = Kπριν − Kμετά. Για μέση δύναμη στο ένα σώμα πρώτα βρες V με ΑΔΟ και μετά τη δική του Δp. Καμία αλλαγή στο σύστημα δεν υπολογίζεται από το Δp ενός μόνο σώματος.\", \"Ακίνητος στόχος, χάνεται 75% → m/(m+M) = 1/4 → M = 3m.\", \"Τρ. 4.94, ΤΘ 15891/2.1, 16263/2.1, 16063/2.1\"]]], [\"D\", \"Χωρίζονται μετά την κρούση\", \"Δύο σώματα μετά σημαίνει δύο τελικές ταχύτητες.\", \"ΑΔΟ και δεύτερο δεδομένο. Αν είναι ελαστική, το δεύτερο δεδομένο είναι η διατήρηση της συνολικής K. Αν δεν ξέρεις το είδος, σύγκρινε τις συνολικές κινητικές στα δύο όρια της κρούσης.\", \"split\", [[\"Ελαστική, ίσες μάζες\", \"Σε κεντρική ελαστική κρούση δύο ίσων μαζών, ανταλλάσσονται οι ταχύτητες. Αν το ένα ήταν ακίνητο, σταματά το εισερχόμενο και ξεκινά ο στόχος.\", \"1 kg με +4 m/s και 1 kg ακίνητο → 0 και +4 m/s μετά, με 8 J πριν και μετά.\", \"Πόστερ 32\"], [\"Ελαστική, διαφορετικές μάζες\", \"Χρειάζεσαι ΑΔΟ και ίσες συνολικές κινητικές. Σε ακίνητο στόχο, αν το εισερχόμενο είναι ελαφρύτερο, γυρίζει. Αν είναι βαρύτερο, συνεχίζει μπροστά.\", \"2 kg με 6 m/s σε ακίνητο 4 kg → −2 και +4 m/s. Κπριν = Κμετά = 36 J.\", \"Τρ. 4.122–4.123, Πόστερ 41\"], [\"Ανελαστική χωρίς συγκόλληση\", \"Δεν βάζεις κοινή V. Σώμα που σταματά ή γυρίζει δεν αρκεί από μόνο του για να αναγνωρίσεις το είδος. Χρησιμοποίησε την πληροφορία για τις τελικές ταχύτητες και έλεγξε Κ.\", \"1 kg με 10 m/s χτυπά ακίνητο 2 kg και το πρώτο σταματά. Το δεύτερο φεύγει με 5 m/s. Κ: 50 → 25 J.\", \"Τρ. 4.93, 4.107–4.108, 4.110, ΤΘ 21437/2.1\"], [\"Διάτρηση κινητού στόχου\", \"Το μικρό σώμα βγαίνει από τον στόχο και έχει δική του τελική ταχύτητα. Ξεχώρισε τι ενέργεια παίρνει ο στόχος, τι κρατά το μικρό σώμα και τι χάνεται συνολικά από την Κ.\", \"0,1 kg με 4 m/s βγαίνει με 1 m/s από ακίνητο στόχο 0,2 kg → ο στόχος φεύγει με 1,5 m/s.\", \"Τρ. 4.121, ΤΘ 16122/2.2, 16245/2.2, Σχ. 13\"], [\"Λοξή κρούση και διαφορετικές εξόδους\", \"Γράφω διατήρηση Pₓ και Pᵧ όπου επιτρέπεται. Ελαστική σημαίνει ότι προσθέτω και εξίσωση ενέργειας, αλλά μπορεί να χρειάζομαι επιπλέον πληροφορία για τις γωνίες.\", \"Αρχική P = (5,0). Αν μετά η p₁ = (2,1), τότε p₂ = (3,−1) σε kg·m/s.\", \"Επέκταση του Πόστερ 5 και 20\"]]], [\"E\", \"Μετά την κρούση: τριβή και έργο\", \"Η τριβή μπορεί να είναι αμελητέα για την κρούση, αλλά όχι για το γλίστρημα.\", \"Σε κάθε φάση ξεχωριστό διάστημα. ΑΔΟ στην κρούση, αν η ώθηση τριβής εκεί είναι αμελητέα. Μετά, ΘΜΚΕ ή Νεύτωνας και κινηματική.\", \"friction\", [[\"Λείο οριζόντιο δάπεδο\", \"Μετά την κρούση, χωρίς οριζόντια δύναμη, η ταχύτητα μένει σταθερή μέχρι να συμβεί κάτι άλλο.\", \"V = 2 m/s → σε 3 s διανύει 6 m. Δεν χρειάζεται νέος υπολογισμός κρούσης.\", \"Τρ. 4.86, 4.120, Πόστερ 21\"], [\"Τραχύ δάπεδο, ενιαίο σώμα\", \"Η τριβή φρενάρει μετά την κρούση. Από απόσταση d βρίσκεις V με V² = 2μgd. Από χρόνο ακινητοποίησης t βρίσκεις V = μgt. Συχνά λύνεις ανάποδα, από την ακινητοποίηση προς την κρούση.\", \"μ = 0,1 και d = 8 m → V = 4 m/s για g = 10. Αυτή είναι η ταχύτητα που βάζεις στην ΑΔΟ.\", \"Τρ. 4.100, 4.109, 4.112–4.113, Σχ. 17\"], [\"Τραχύ δάπεδο, χωριστά σώματα\", \"Κάθε σώμα έχει δική του αρχική ταχύτητα, φορά και χρόνο ακινητοποίησης. Αφού σταματήσει, δεν συνεχίζεις την εξίσωσή του σαν να γυρίζει μόνο του.\", \"Φεύγουν με 1 m/s αριστερά και 2 m/s δεξιά, μ = 0,2. Το πρώτο σταματά στα 0,5 s. Τότε απέχουν 1 m.\", \"Τρ. 4.115, 4.122\"], [\"Ανηφόρα λεία ή τραχιά\", \"Σε λεία ράμπα: ΑΔΜΕ, h = V²/(2g) αν σταματήσει. Με τριβή: ΘΜΚΕ με έργο βάρους και τριβής. Αν ζητούν τι γίνεται μετά τη στάση, ελέγχω αν η στατική τριβή το κρατά.\", \"V = 20 m/s και επιβράδυνση 10 m/s² → s = 20 m. Για ημφ = 0,6, h = 12 m.\", \"Τρ. 4.114, Περιπ. Δ5\"], [\"Μετά συμπιέζει ιδανικό ελατήριο\", \"Αν δεν υπάρχει τριβή, η Κ που απέμεινε μετά την κρούση γίνεται δυναμική ενέργεια ελατηρίου. Στο μέγιστο της συμπίεσης υ = 0 στιγμιαία.\", \"Συσσωμάτωμα 2 kg με V = 3 m/s, αρχικά ασυμπίεστο ελατήριο k = 200 N/m → xmax = 0,30 m.\", \"Παραλλαγή του μοτίβου ΑΔΟ → ΑΔΜΕ\"]]], [\"F\", \"Πτώση, βολή και κρούση σε φάσεις\", \"Το τέλος της μίας φάσης δίνει την αρχή της επόμενης.\", \"Πρώτα εντόπισε πότε χρειάζεσαι την ταχύτητα. Το ύψος δίνει το μέτρο μέσω ΑΔΜΕ. Ο χρόνος και το βεληνεκές χρειάζονται κινηματική.\", \"flight\", [[\"Πτώση ή εκκρεμές πριν από την κρούση\", \"Ξεκινά από ύψος και φτάνει σε άλλο σώμα: πρώτα ΑΔΜΕ μέχρι πριν την επαφή, εφόσον δεν υπάρχει απώλεια. Μετά γράφω τον νόμο της συγκεκριμένης κρούσης.\", \"Από ηρεμία, κατεβαίνει 1,25 m χωρίς τριβή → υ = 5 m/s. Κολλά με ίση ακίνητη μάζα σε οριζόντια κρούση → V = 2,5 m/s.\", \"Περιπ. Δ5, Τρ. 4.104 για τη φάση πτώσης\"], [\"Κρούση στην άκρη τραπεζιού\", \"Αν το σώμα φεύγει οριζόντια, t = √(2H/g) και x = Vt. Αν δίνεται το σημείο πτώσης, βρίσκω πρώτα V και μετά γυρίζω στην ΑΔΟ. Κοινή V μόνο αν κολλήσουν.\", \"Στην 4.121 ο στόχος πέφτει από 1,8 m και πάει 3 m μακριά → t = 0,6 s και V = 5 m/s. Το σώμα που τον διαπέρασε έχει ξεχωριστή υ.\", \"Τρ. 4.121, Πόστερ 29, Περιπ. Δ1\"], [\"Διάσπαση στην κορυφή κατακόρυφης βολής\", \"Πριν από τη διάσπαση στην κορυφή P = 0. Αν το ένα από δύο θραύσματα φεύγει οριζόντια, και το άλλο φεύγει οριζόντια στην αντίθετη φορά. Κοινός χρόνος πτώσης αν ξεκινούν από ίδιο ύψος με υᵧ = 0.\", \"Από H = 180 m με g = 10, πέφτουν για 6 s. Αν οι οριζόντιες ταχύτητες είναι 50 και 150 m/s αντίθετα, απέχουν 1.200 m στο έδαφος.\", \"Τρ. 4.116, ΤΘ 19653/2.2, 21763/2.1, Περιπ. Δ2\"], [\"Δεν φεύγουν και τα δύο οριζόντια\", \"Ίδιο ύψος δεν σημαίνει ίδιος χρόνος αν οι κατακόρυφες συνιστώσες διαφέρουν. Γράφεις την κατακόρυφη εξίσωση για κάθε σώμα χωριστά. Η οριζόντια συνιστώσα δεν αλλάζει χωρίς αέρα.\", \"Από 5 m με g = 10, οριζόντια εκκίνηση δίνει 1 s. Με αρχική κατακόρυφη υ = +5 m/s, η πτώση διαρκεί περίπου 1,62 s.\", \"Παραλλαγή της Περιπ. Δ2\"]]], [\"G\", \"Κρούση και κυκλική κίνηση\", \"Ίδια εφαπτομενική ΑΔΟ, διαφορετική τροχιά μετά.\", \"Στην κρούση κοιτάω την εφαπτομένη αν η ώθηση της στήριξης είναι ακτινική. Μετά κοιτάω αν αλλάζει το ύψος. Η κεντρομόλος είναι η ακτινική συνισταμένη, όχι πρόσθετη δύναμη.\", \"circle\", [[\"Οριζόντιος κύκλος σε λείο δάπεδο\", \"Πριν και μετά ισχύει T = mυ²/R, με τη σωστή μάζα κάθε φορά. Με αρνητική V το συσσωμάτωμα γυρίζει ανάποδα. Το μέτρο της υ μένει σταθερό μετά, όχι η ορμή ως διάνυσμα.\", \"Στην 4.117: 4·5 − 2·16 = 6V → V = −2 m/s. Η τάση πέφτει από 50 σε 12 N.\", \"Τρ. 4.117, Περιπ. Δ4, ΤΘ 16299/2.2 για ρυθμό Δp\"], [\"Κατακόρυφος κύκλος και απλή επιστροφή\", \"Μετά την κρούση, ΑΔΜΕ: υ² = V² − 2gh. Η τάση δεν κάνει έργο. Αν σταματήσει ενώ το νήμα είναι ακόμη τεντωμένο, h = V²/(2g) και μετά γυρίζει.\", \"Με V = 2 m/s, ℓ = 1 m και g = 10, ανεβαίνει 0,20 m και επιστρέφει. Δεν είναι ομαλή κυκλική κίνηση.\", \"Πόστερ 24–25, βαλλιστικό εκκρεμές\"], [\"Νήμα: επιστροφή, χαλάρωση ή κύκλος\", \"Θέτω q = V²/(gℓ). Για 0 < q ≤ 2 επιστρέφει. Για 2 < q < 5 η τάση μηδενίζεται πριν από την κορυφή και αρχίζει βολή. Για q ≥ 5 ολοκληρώνει τον κύκλο. Στο q = 5 η τάση μηδενίζεται στιγμιαία στην κορυφή.\", \"Με ℓ = 1 m, g = 10 και V² = 45 m²/s² → q = 4,5. Το νήμα χαλαρώνει πάνω από τα 90°, ενώ το σώμα κινείται ακόμη.\", \"Επέκταση Πόστερ 24–25\"], [\"Αβαρής άκαμπτη ράβδος: μπορεί να σπρώξει\", \"Για 0 < q < 4 σταματά και επιστρέφει. Για q = 4 πλησιάζει οριακά την κορυφή χωρίς να την περάσει σε πεπερασμένο χρόνο. Για q > 4 κάνει πλήρη κύκλο. Με μηδενική V στον πυθμένα μένει ακίνητο.\", \"Στο ίδιο q = 4,5, η ράβδος κάνει κύκλο. Για ράβδο με μάζα χρειάζεται στροφορμή και ενέργεια του περιστρεφόμενου συστήματος.\", \"Συγκριτική επέκταση: νήμα–ράβδος\"]]], [\"H\", \"Απώθηση, ανάκρουση και διάσπαση\", \"Κάτι χωρίζει σε μέρη ή τα μέρη σπρώχνονται. Η συνολική ορμή δεν δημιουργείται από μέσα.\", \"ΑΔΟ στο κατάλληλο σύστημα, με αμελητέα εξωτερική ώθηση. Από ηρεμία, δύο μέρη παίρνουν αντίθετες ορμές ίσου μέτρου. Η πηγή της νέας Κ μπορεί να είναι ελατήριο, μυϊκή ή άλλη εσωτερική ενέργεια.\", \"recoil\", [[\"Παγοδρόμοι: σπρώχνουν ή τραβούν\", \"Από ηρεμία παίρνουν αντίθετες ορμές. Με σπρώξιμο απομακρύνονται, με τράβηγμα πλησιάζουν. Το ελαφρύτερο έχει μεγαλύτερη ταχύτητα.\", \"Παγοδρόμοι 60 και 90 kg, μετά το τράβηγμα με ταχύτητες 3 και 2 m/s προς αλλήλους. Απόσταση 30 m → συναντιούνται σε 6 s.\", \"Τρ. 4.95–4.96, ΤΘ 16709/2.1, 19230/2.2\"], [\"Ελατήριο ανάμεσα σε δύο αμαξίδια\", \"Μετά την απώθηση, το ελαφρύ είναι ταχύτερο. Σε ίδιο χρόνο πάνω σε λείο επίπεδο, οι αποστάσεις είναι αντιστρόφως ανάλογες των μαζών. Μηχανισμός που δρα μόνο εσωτερικά δεν μετακινεί το κέντρο μάζας.\", \"400 g και 800 g → το ελαφρύ διανύει διπλάσια απόσταση στον ίδιο χρόνο.\", \"Τρ. 4.99, ΤΘ 14748/2.1–2.2, 21817/2.1\"], [\"Διάσπαση από ηρεμία ή εν κινήσει\", \"Από ηρεμία, δύο κομμάτια βγαίνουν με αντίθετες ίσες σε μέτρο ορμές, αλλά το ελαφρύ έχει περισσότερη Κ. Αν το σύστημα κινούνταν, η αρχική συνολική ορμή δεν είναι μηδέν.\", \"Σώμα 3m κινείται με υ. Το κομμάτι m φεύγει με 4υ στην ίδια φορά → το 2m φεύγει με −υ/2.\", \"Τρ. 4.97, ΤΘ 16066/2.1, 16209/2.1, 16107/2.2\"], [\"Βάρκα ή σανίδα: μετράει το σύστημα αναφοράς\", \"Με αμελητέα εξωτερική οριζόντια ώθηση, βάρκα και άνθρωπος ανταλλάσσουν ορμή. Στην ΑΔΟ βάζω ταχύτητες ως προς ακτή ή έδαφος, όχι αυθαίρετα ως προς τη βάρκα. Μετά ελέγχω την αντίσταση του νερού.\", \"80 kg πηδούν με 2,5 m/s ως προς την ακτή από ακίνητη βάρκα 100 kg → η βάρκα αποκτά 2 m/s αντίθετα.\", \"Τρ. 4.98, 4.118–4.119, Σχ. 11, Πόστερ 14, 38, 43\"], [\"Τρία θραύσματα ή εκροή μάζας\", \"Για τρία κομμάτια από ηρεμία τα βέλη ορμής κλείνουν τρίγωνο. Σε εκροή συμπεριλαμβάνω και τη μάζα που φεύγει για να ορίσω το σύστημα.\", \"Αν p₁ = (3,0) και p₂ = (0,4), τότε p₃ = (−3,−4) kg·m/s και |p₃| = 5.\", \"Πόστερ 37, 42, ΤΘ 21691/2.2, 21819/2.1\"]]], [\"I\", \"Διαδοχικά γεγονότα και ωθήσεις\", \"Άλλαξε γραμμή όταν αλλάξει ποιος αλληλεπιδρά ή τι δύναμη δρα.\", \"Μη χρησιμοποιείς μία εξίσωση ορμής από την αρχή ως το τέλος αν μεσολαβεί ώθηση από τοίχο ή δάπεδο. Η τελική ταχύτητα κάθε φάσης περνά στην αρχή της επόμενης.\", \"chain\", [[\"Δύο κρούσεις, τρία σώματα\", \"ΑΔΟ χωριστά στην 1η κρούση και στη 2η με τις μάζες που συμμετέχουν. Αν όλο το σύστημα είναι μονωμένο, η συνολική ΑΔΟ είναι επιπλέον έλεγχος, αλλά δεν δίνει από μόνη της τα ενδιάμεσα.\", \"Στην 4.120 τα πρώτα 5 kg κολλούν και μένουν ακίνητα. Το τρίτο σώμα 3 kg φτάνει με 4 m/s → τα 8 kg κινούνται με 1,5 m/s.\", \"Τρ. 4.120\"], [\"Πρώτα κρούση σωμάτων, μετά τοίχος\", \"ΑΔΟ για τα δύο σώματα στην πρώτη κρούση, όχι στο χτύπημα του ενός στον τοίχο. Μετά την ανάκλαση, σύγκρινε θέσεις και ταχύτητες για να δεις αν θα ξανασυναντηθούν.\", \"Στην 4.123 μετά την πρώτη κρούση: −3 και +1 m/s. Ο τοίχος κάνει το +1 σε −1. Δεν προλαβαίνει το πρώτο που απομακρύνεται ήδη με −3.\", \"Τρ. 4.123\"], [\"Η δύναμη παύει, η τριβή συνεχίζει\", \"Μέχρι να σβήσει η εξωτερική δύναμη δρουν δύναμη και τριβή. Μετά μένει η τριβή ώσπου να σταματήσει. Άλλαξε κλίση στο p–t ακριβώς στην αλλαγή φάσης.\", \"Τριβή 3 N για 15 s μέχρι να σταματήσει → η ορμή στην αρχή του φρεναρίσματος ήταν 45 kg·m/s.\", \"Τρ. 4.102, 4.106\"], [\"Ροή από πολλές μικρές κρούσεις\", \"Βρίσκω τη μεταβολή ορμής ανά σωματίδιο και πολλαπλασιάζω με τον αριθμό που προσπίπτει ανά δευτερόλεπτο. Αν ανακλώνται αντί να σταματούν, αλλάζει η Δp κάθε σωματιδίου.\", \"500 σταγόνες/s σταματούν, καθεμία με |Δp| = 0,00051 N·s → μέση δύναμη πρόσκρουσης 0,255 N.\", \"Σχ. 7, Πόστερ 35, 39\"], [\"Σταματά στιγμιαία ή μένει εκεί;\", \"Σε λείο επίπεδο χωρίς οριζόντια δύναμη, V = 0 μπορεί να σημαίνει ότι μένει εκεί. Σε κορυφή κατακόρυφης βολής ή στο σημείο επιστροφής εκκρεμούς το v = 0 δεν συνεπάγεται μόνιμη στάση.\", \"Ακριβώς στην κορυφή της βολής p = 0 αλλά dp/dt = −mg. Αντίθετα, τα δύο σώματα της 1ης κρούσης της 4.120 μένουν ακίνητα μέχρι τη 2η κρούση.\", \"Σχ. ερ. 7, 9, 10, Τρ. 4.120\"]]], [\"J\", \"Ηλεκτρικό και βαρυτικό πεδίο\", \"Συνδυαστικά θέματα: ξεχώρισε εσωτερική αλληλεπίδραση από εξωτερικό πεδίο.\", \"ΑΔΟ όταν η συνολική εξωτερική ώθηση μηδενίζεται ή είναι αμελητέα. ΑΔΜΕ όταν οι δυνάμεις που κάνουν έργο είναι συντηρητικές. Αυτά είναι δύο διαφορετικά κριτήρια.\", \"field\", [[\"Δύο φορτία αφήνονται ελεύθερα\", \"Ομόσημα απομακρύνονται, ετερόσημα πλησιάζουν. Σε λείο οριζόντιο επίπεδο χωρίς εξωτερικό πεδίο, η συνολική ορμή είναι μηδέν κάθε στιγμή, ενώ η Κ προέρχεται από μείωση της ηλεκτρικής U.\", \"Αν m₂ = 2m₁ και ξεκινούν ακίνητα → |υ₁| = 2|υ₂| και Κ₁ = 2Κ₂ σε κάθε σημείο όπου κινούνται.\", \"ΤΘ 19480/2.1, 21761/2.2, Περιπ. Β5\"], [\"Ομόσημα φορτία που πλησιάζουν\", \"Στην ελάχιστη απόσταση της μετωπικής προσέγγισης μηδενίζεται η σχετική ταχύτητα, όχι απαραίτητα οι δύο ταχύτητες ως προς το εργαστήριο. ΑΔΟ για την κοινή στιγμιαία υ, ΑΔΜΕ για την απόσταση.\", \"m με +u και 4m με −u → P = −3mu. Στην ελάχιστη απόσταση έχουν και τα δύο υ = −3u/5.\", \"ΤΘ 20893/2.2, Περιπ. Β5\"], [\"Δορυφόροι συγκρούονται σε τροχιά\", \"Για τον σύντομο χρόνο της κρούσης η ώθηση της βαρύτητας μπορεί να αγνοηθεί. Μετά η βαρύτητα συνεχίζει να δρα, άρα η ορμή του συσσωματώματος δεν μένει σταθερή.\", \"Ίσες μάζες, ίδια κυκλική τροχιά, αντίθετες ταχύτητες → V = 0 αμέσως μετά την πλαστική κρούση. Στη συνέχεια το σώμα πέφτει προς τη Γη.\", \"ΤΘ 16390/2.1, Περιπ. Β6\"], [\"Διάσπαση σε βαρυτικό πεδίο και διαφυγή\", \"Ταχύτητα πριν από τροχιά ή ΑΔΜΕ → ΑΔΟ στη σύντομη διάσπαση → ξεχωριστή ΑΔΜΕ για κάθε θραύσμα. Σε μεγάλες αποστάσεις δεν βάζω mgh: χρησιμοποιώ U = −GMm/r.\", \"Για οριακή διαφυγή, στο άπειρο υ → 0 και U → 0. Επομένως, στη θέση της διάσπασης το συγκεκριμένο θραύσμα πρέπει να έχει Κ + U = 0.\", \"Περιπ. Β6\"]]]], \"colors\": [\"#0E6555\", \"#1954A4\", \"#7142A2\", \"#AA421E\", \"#936117\", \"#17708C\", \"#3157A8\", \"#8D386B\", \"#4F626D\", \"#596D2C\"], \"index\": {\"A\": [\"67-79 83-85 101-102 105-106\", \"21388/2.1 15997/2.1 20047/2.1 16105/2.1 16227/2.1 21401/2.2 16049/2.2 16875/2.2 16388/2.1\", \"1 2 3 6 8 9 12\", \"1 2 4 8 11 19\", \"1 2 6-9 11-12\", \"Α1–Α6\"], \"B\": [\"80-82 103-104\", \"16045/2.2 16120/2.2\", \"5 10\", \"5 6 17 18\", \"3-5 33-35\", \"Α2–Α3\"], \"C\": [\"86-92 94 111\", \"16063/2.1 21853/2.1 19652/2.2 15891/2.1 20048/2.1 16263/2.1 18913/2.1 16037/2.1 16037/2.2 16046/2.2 16070/2.2 16067/2.2 16069/2.2 21439/2.2 16116/2.2 16708/2.1 16733/2.2 20231/2.2 21173/2.1 16264/2.2\", \"15 16\", \"15 16\", \"16-21 30\", \"Β1, Γ1–Γ2\"], \"D\": [\"93 107-108 110\", \"21437/2.1 16122/2.2 16245/2.2\", \"13\", \"\", \"23 31 32 41\", \"Β2, Γ3\"], \"E\": [\"100 109 112-115 122\", \"\", \"17\", \"\", \"22\", \"Δ3\"], \"F\": [\"116 121\", \"21763/2.1 19653/2.2\", \"4\", \"12\", \"10 28 29 40\", \"Δ1–Δ2, Δ5\"], \"G\": [\"117\", \"16299/2.2\", \"\", \"\", \"24-25\", \"Δ4\"], \"H\": [\"95-99 118-119\", \"16107/2.2 14748/2.1 14748/2.2 21817/2.1 16103/2.2 21490/2.2 16709/2.1 19230/2.2 19232/2.1 16066/2.1 16209/2.1 16064/2.1 21691/2.2 21819/2.1 16119/2.1\", \"11 14\", \"3 13 14\", \"13-15 26-27 36-38 42-43\", \"Β3–Β4\"], \"I\": [\"120 123\", \"\", \"7\", \"7 9 10\", \"39\", \"\"], \"J\": [\"\", \"16390/2.1 19480/2.1 21761/2.2 20893/2.2\", \"\", \"\", \"\", \"Β5–Β6\"]}, \"urls\": [[\"Ορμή και κρούσεις · αρχική σελίδα\", \"https://chioshotel.gr/mixalis/ormi/\"], [\"Λυμένες ασκήσεις Τριπολίτη\", \"https://chioshotel.gr/mixalis/ormi/#askiseis\"], [\"Τράπεζα Θεμάτων · Θέμα 2\", \"https://chioshotel.gr/mixalis/ormi/#trapeza\"], [\"20 περιπτώσεις και συνδυαστικά θέματα\", \"https://chioshotel.gr/mixalis/ormi/periptoseis/\"], [\"Σχολικό βιβλίο · διαδραστικό μάθημα\", \"https://chioshotel.gr/mixalis/ormi/#mathima\"]]};\nconst $ = s=>document.querySelector(s);\nlet current=0, choice=0, val=0, running=false, tick=0, last=0;\nconst reduced = matchMedia('(prefers-reduced-motion: reduce)').matches;\nconst S = {\nforce:{name:'Ορμή και συνισταμένη δύναμη', options:['Επιτάχυνση','Φρενάρισμα'],notes:['Θετική κλίση p–t → θετική συνισταμένη.','Αρνητική κλίση p–t → αρνητική συνισταμένη.']},\nbounce:{name:'Τρεις αναπηδήσεις στο πάτωμα', options:['Αφήνεται από 10 m','Ρίχνεται κάτω με 10 m/s','Ρίχνεται πάνω με 10 m/s'],notes:['Αρχική κορυφή 10 m. Επόμενες κορυφές 7 → 4,9 → 3,43 m.','Πρώτη κρούση νωρίτερα. Κορυφές 10,5 → 7,35 → 5,15 m.','Ανεβαίνει πρώτα στα 15 m. Ίδια ύψη αναπήδησης όπως στη ρίψη προς τα κάτω.']},\nstick:{name:'Δύο ίσες μάζες που κολλάνε', options:['Ακίνητος στόχος','Ίδια φορά','Ίσες και αντίθετες ορμές'],notes:['4 και 0 m/s → κοινή ταχύτητα +2 m/s.','4 και 2 m/s → κοινή ταχύτητα +3 m/s.','+4 και −4 m/s → κολλάνε και μένουν ακίνητα.']},\nsplit:{name:'Ίδιες αρχικές συνθήκες, άλλη κρούση', options:['Ελαστική','Ανελαστική χωρίς συγκόλληση'],notes:['Ίσες μάζες. 4 και 0 m/s → 0 και 4 m/s.','Ίσες μάζες. 4 και 0 m/s → 1 και 3 m/s στο παράδειγμα.']},\nfriction:{name:'Μετά την κρούση στο δάπεδο', options:['Λείο','Με τριβή'],notes:['Χωρίς οριζόντια δύναμη η ταχύτητα μένει σταθερή.','Η τριβή μειώνει την ταχύτητα μέχρι να σταματήσει.']},\nflight:{name:'Δύο οριζόντιες βολές από το ίδιο ύψος', options:['Αντίθετες φορές','Ίδια φορά'],notes:['Ίδιος χρόνος πτώσης. Τα βεληνεκή προστίθενται.','Ίδιος χρόνος πτώσης. Η απόσταση στο έδαφος είναι η διαφορά των βεληνεκών.']},\ncircle:{name:'Η ίδια ταχύτητα με νήμα ή ράβδο', options:['Οριζόντιος κύκλος','Κατακόρυφος · νήμα','Κατακόρυφος · ράβδος'],notes:['Η κρούση της 4.117 αντιστρέφει τη φορά. Μετά, σταθερό μέτρο ταχύτητας.','Με V²/(gℓ) = 4,5 το νήμα χαλαρώνει και το σώμα συνεχίζει σαν βολή.','Με V²/(gℓ) = 4,5 η ράβδος κρατά το σώμα στον κύκλο.']},\nrecoil:{name:'Ίσες και αντίθετες ορμές από ηρεμία', options:['Απώθηση','Έλξη'],notes:['Το ελαφρύτερο σώμα φεύγει πιο γρήγορα.','Τα σώματα πλησιάζουν αντί να απομακρύνονται.']},\nchain:{name:'Η πρώτη κρούση δίνει το αρχικό σημείο της δεύτερης', options:['Δύο πλαστικές κρούσεις'],notes:['4.120 · Τα δύο πρώτα σώματα κολλάνε και μένουν ακίνητα μέχρι να έρθει το τρίτο.']},\nfield:{name:'Κίνηση δύο φορτίων από ηρεμία', options:['Ομόσημα','Ετερόσημα'],notes:['Απωθούνται και απομακρύνονται. Η συνολική ορμή παραμένει μηδέν.','Έλκονται και πλησιάζουν. Η συνολική ορμή παραμένει μηδέν.']}\n};\nconst bc=['#1659a5','#aa421e','#0e6555'];\nconst line=(x,y,a,b,c='#adbec3',w=1.7, dash='')=>`<line x1=\"${x}\" y1=\"${y}\" x2=\"${a}\" y2=\"${b}\" stroke=\"${c}\" stroke-width=\"${w}\" ${dash?'stroke-dasharray=\"5 5\"':''}/>`;\nconst dot=(x,y,r,c)=>`<circle cx=\"${x}\" cy=\"${y}\" r=\"${r}\" fill=\"${c}\"/>`;\nconst txt=(x,y,t,c='#435966')=>`<text x=\"${x}\" y=\"${y}\" fill=\"${c}\" font-size=\"13\" font-family=\"system-ui,sans-serif\">${t}</text>`;\nconst path=(points,c,w=2.5,dash=false)=>`<polyline points=\"${points.map(a=>a.join(',')).join(' ')}\" fill=\"none\" stroke=\"${c}\" stroke-width=\"${w}\" stroke-linecap=\"round\" stroke-linejoin=\"round\" ${dash?'stroke-dasharray=\"5 5\"':''}/>`;\nconst sample=(f,n=80)=>Array.from({length:n+1},(_,i)=>f(i/n));\nfunction draw(){\n const kind=MAP.families[current][4], q=val/1000, y=118;\n let d='', label='';\n if(kind==='force'){\n  const end=p=>choice?[45+340*p,40+92*p]:[45+340*p,132-92*p];\n  d=line(45,144,390,144)+line(45,144,45,26)+txt(29,30,'p')+txt(388,163,'t')+path(sample(end),bc[0])+dot(...end(q),6,bc[1]);\n }else if(kind==='bounce'){\n  const u=[0,-10,10][choice], g=10, h0=10, start=Math.sqrt(u*u+200);\n  const first=(u+start)/g;\n  let parts=[[0,h0,u,first]],t=first, vv=start;\n  for(let i=0;i<3;i++){vv*=Math.sqrt(.7);parts.push([t,0,vv,(i===2?1:2)*vv/g]);t+=parts.at(-1)[3];}\n  const point=t0=>{const [st,h,v]=parts.reduce((a,b)=>b[0]<=t0+1e-9?b:a,parts[0]);const z=t0-st;return [25+370*t0/9.0,142-7.4*(h+v*z-5*z*z)];};\n  d=line(25,142,395,142)+txt(29,22,'ύψος')+txt(353,169,'χρόνος');\n  for(let i=0;i<parts.length;i++){\n   const [st,h,v,dt]=parts[i];\n   d+=path(sample(p=>point(st+p*dt),45),bc[0]);\n   if(i>0)d+=dot(...point(st),3,bc[1])+txt(point(st)[0]-5,160,i+'η');\n  }\n  d+=dot(...point(q*t),6,bc[1]);\n }else if(kind==='stick'||kind==='split'){\n  let modes=kind==='stick'?[[4,0,2,2],[4,2,3,3],[4,-4,0,0]]:[[4,0,0,4],[4,0,1,3]];\n  const [a,b,af,bf]=modes[choice], z=q-.5, x1=188+z*(z<0?a:af)*55, x2=208+z*(z<0?b:bf)*55;\n  d=line(25,y+10,395,y+10)+dot(x1,y,10,bc[0])+dot(x2,y,10,bc[1]);label=q<.5?'Πριν':q===.5?'Κρούση':'Μετά';\n }else if(kind==='friction'){\n  const progress=choice?2*Math.min(q,.75)/.75-(Math.min(q,.75)/.75)**2:q;\n  d=line(25,y+10,395,y+10)+dot(55+290*progress,y,10,bc[0]);if(choice)d+=path([[50+290*progress,90],[27+290*progress,90],[33+290*progress,85],[27+290*progress,90],[33+290*progress,95]],bc[1]);\n }else if(kind==='flight'){\n  const f=(r,k)=>[210+r*k,35+109*r*r], k=choice?145:-155;\n  d=line(25,144,395,144)+path(sample(r=>f(r,k)),bc[0])+path(sample(r=>f(r,90)),bc[1])+dot(...f(q,k),6,bc[0])+dot(...f(q,90),6,bc[1]);\n }else if(kind==='circle'){\n  const R=58,cx=210,cy=85;\n  const orbit=a=>[cx+R*Math.sin(a),cy+R*Math.cos(a)];\n  const ref=sample(r=>orbit(r*2*Math.PI));\n  let p,anchor=true;\n  if(choice===1){\n   const stop=Math.acos(-2.5/3), sx=Math.sin(stop), sy=Math.cos(stop), speed=Math.sqrt(-sy), dt=q>.65?(q-.65)/.35*(-4*(-speed*sx)):0;\n   const air=t=>[cx+R*(sx+speed*sy*t),cy+R*(sy-speed*sx*t+.5*t*t)];\n   d=path(ref,'#adbec3',1.5)+path(sample(r=>orbit(r*stop)),bc[0])+path(sample(r=>air(r*4*speed*sx)),bc[1],2,true);\n   p=q<=.65?orbit(q/.65*stop):air(dt);anchor=q<=.65;\n  }else{\n   d=path(ref,bc[0]);p=orbit((choice===0?-1:1)*q*2*Math.PI);\n  }\n  d+=dot(cx,cy,3,'#435966')+dot(...p,7,bc[1]);if(anchor)d+=line(cx,cy,...p,'#435966',1.5);\n }else if(kind==='recoil'||kind==='field'){\n  const t=q**(kind==='field'?1.65:1), x1=choice?80+98*t:190-125*t, x2=choice?310-65*t:220+75*t;\n  d=line(25,y+15,395,y+15)+dot(x1,y,9,bc[0])+dot(x2,y,14,bc[1]);\n  if(kind==='field')d+=txt(x1-4,y+4,'+','#fff')+txt(x2-4,y+4,choice?'−':'+','#fff');\n }else{\n  const first=Math.min(q/.40,1), next=Math.max(0,(q-.73)/.27), third=Math.min(q/.73,1);\n  const base=q<.73?210:210+97*next;\n  d=line(25,y+12,395,y+12)+dot(145+55*first+(base-210),y,9,bc[0])+dot(282-63*first+(base-210),y,9,bc[1])+dot(36+144*third+(base-210),y,10,bc[2]);\n  label=q<.4?'Πριν την 1η κρούση':q<.73?'Προς τη 2η κρούση':'Μετά τη 2η κρούση';\n }\n $('#scene').innerHTML=d+(label?txt(19,24,label):'');\n}\nfunction setRun(v){running=v;$('#play').textContent=v?'❚❚ Παύση':'▶ Κίνηση';$('#play').setAttribute('aria-pressed',String(v));if(!v&&tick)cancelAnimationFrame(tick);if(v){last=0;tick=requestAnimationFrame(frame);}}\nfunction frame(ts){if(!running)return;if(!last)last=ts;val=Math.min(1000,val+(ts-last)*.20);last=ts;$('#seek').value=val;draw();if(val>=1000)setRun(false);else tick=requestAnimationFrame(frame);}\nfunction variants(){\n const item=MAP.families[current], scene=S[item[4]];\n $('#scene-title').textContent=scene.name;\n $('#scenarios').innerHTML=scene.options.length>1?'<label style=\"flex:0 1 auto\"><span class=\"sr-only\">Παραλλαγή σχήματος</span><select id=\"motion-case\">'+scene.options.map((v,i)=>`<option value=\"${i}\">${v}</option>`).join('')+'</select></label>':'';\n if($('#motion-case'))$('#motion-case').addEventListener('change',e=>{choice=Number(e.target.value);setRun(false);val=0;$('#seek').value=0;$('#note').textContent=scene.notes[choice];draw();});\n $('#note').textContent=scene.notes[choice];draw();\n}\nfunction openFamily(i){\n setRun(false);current=i;choice=0;val=0;$('#seek').value=0;\n const [key,title,hook,route,kind,cases]=MAP.families[i];\n document.documentElement.style.setProperty('--accent',MAP.colors[i]);\n for(const [j,b] of [...$('#families').children].entries())b.setAttribute('aria-pressed',String(i===j));\n $('#tag').textContent='Οικογένεια '+key;$('#title').textContent=title;$('#hook').textContent=hook;$('#route').textContent=route;\n $('#cases').replaceChildren(...cases.map(([name,body,ex,ref],j)=>{\n  const d=document.createElement('details');d.open=j===0;\n  const su=document.createElement('summary'),sp=document.createElement('span');sp.textContent=key+(j+1);su.append(sp,document.createTextNode(name));d.append(su);\n  for(const [value,cls] of [[body,''],['Παράδειγμα · '+ex,'example'],['Σχετικές ασκήσεις · '+ref,'ref']]){const p=document.createElement('p');p.textContent=value;p.className=cls;d.append(p);}\n  return d;\n }));\n const labels=['Τριπολίτης (κεφ. 4)','Τράπεζα Θεμάτων (κωδικός/ερώτημα)','Σχολικό βιβλίο · ασκήσεις','Σχολικό βιβλίο · ερωτήσεις','Πόστερ','Σελίδα περιπτώσεων'];\n $('#index').replaceChildren(...MAP.index[key].flatMap((v,j)=>{if(!v)return[];const p=document.createElement('p');p.textContent=labels[j]+' · '+v;return[p];})); variants();\n}\n$('#families').replaceChildren(...MAP.families.map((f,i)=>{const b=document.createElement('button');b.style.setProperty('--tone',MAP.colors[i]);b.type='button';const s=document.createElement('strong');s.textContent=f[0];b.append(s,document.createTextNode(f[1]));b.addEventListener('click',()=>openFamily(i));return b;}));\n$('#play').addEventListener('click',()=>{if(reduced){val=val>=1000?0:Math.min(1000,val+250);$('#seek').value=val;draw();return;}if(!running&&val>=1000){val=0;$('#seek').value=0;draw();}setRun(!running);});\nif(reduced)$('#play').setAttribute('aria-label','Επόμενο βήμα κίνησης');\n$('#seek').addEventListener('input',e=>{setRun(false);val=Number(e.target.value);draw();});\n$('#sources').append(document.createTextNode('Ασκήσεις και πηγές · '));for(const [name,url] of MAP.urls){const a=document.createElement('a');a.href=url;a.textContent=name;if(window.parent!==window)a.target='_top';$('#sources').append(a,document.createTextNode(' · '));}\nopenFamily(0);\n// In the lesson frame, report the content height rather than the viewport height.\nif (window.parent !== window) {\n  const main = document.querySelector(\"main\");\n  const reportHeight = () => window.parent.postMessage(\n    { type: \"ormi-map-height\", height: Math.ceil(main.getBoundingClientRect().height) },\n    window.location.origin\n  );\n  window.addEventListener(\"message\", event => {\n    if (event.origin === window.location.origin && event.source === window.parent && event.data === \"ormi-map-ping\") reportHeight();\n  });\n  new ResizeObserver(reportHeight).observe(main);\n  reportHeight();\n}\n\n</script>\n</body></html>\n";
export const ORMI_MAP_PDF_BASE64 = "";
